package com.anysale.lead.domain.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="sales_playbook") public class SalesPlaybook { @Id @Column(columnDefinition="uuid") private UUID id; @Column(name="tenant_id",nullable=false,updatable=false) private String tenantId; @Column(nullable=false,length=120) private String name; @Column(length=500) private String description; private boolean active=true; @Column(name="is_default",nullable=false) private boolean defaultPlaybook; private int version=1; @ElementCollection @CollectionTable(name="sales_playbook_category",joinColumns=@JoinColumn(name="playbook_id")) @Column(name="category",length=80) private Set<String> categories=new LinkedHashSet<>(); @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; @PrePersist void pre(){if(id==null)id=UUID.randomUUID();Instant n=Instant.now();if(createdAt==null)createdAt=n;updatedAt=n;} @PreUpdate void up(){updatedAt=Instant.now();version++;} public UUID getId(){return id;} public String getTenantId(){return tenantId;} public void setTenantId(String v){tenantId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public boolean isDefaultPlaybook(){return defaultPlaybook;} public void setDefaultPlaybook(boolean v){defaultPlaybook=v;} public int getVersion(){return version;} public Set<String> getCategories(){return categories;} public void setCategories(Set<String> v){categories=v;} }
